module RapidRailsTemplate
  class Configuration
    PROFILE_FEATURES = %w[screen_name display_name avatar].freeze

    VALID_VALUES = {
      "pwa" => %w[use skip],
      "web_push" => %w[use skip],
      "active_job" => %w[solid_queue skip],
      "solid_cache" => %w[use skip],
      "account_authentication" => %w[devise wallet_siwe],
      "profile_features" => PROFILE_FEATURES,
      "api" => %w[enable disable],
      "action_cable" => %w[solid_cable skip],
      "mail" => %w[auto use skip],
      "action_text" => %w[use skip],
      "deployment" => %w[dokploy none]
    }.freeze

    DEFAULTS = {
      "pwa" => "skip",
      "web_push" => "skip",
      "active_job" => "skip",
      "solid_cache" => "use",
      "account_authentication" => "devise",
      "profile_features" => PROFILE_FEATURES,
      "api" => "enable",
      "action_cable" => "skip",
      "mail" => "auto",
      "action_text" => "use",
      "deployment" => "dokploy"
    }.freeze

    attr_reader :answers, :values, :reasons

    def self.build(answers)
      new(answers).tap(&:validate!)
    end

    def initialize(answers)
      @answers = DEFAULTS.merge(answers.transform_keys(&:to_s)).transform_values do |value|
        value.is_a?(Array) ? value.dup.freeze : value
      end.freeze
      @values = @answers.dup
      @reasons = {}
      normalize!
      @values.freeze
      @reasons.freeze
      freeze
    end

    def [](key)
      values.fetch(key.to_s)
    end

    def to_h
      { "answers" => answers, "values" => values, "reasons" => reasons }
    end

    def validate!
      VALID_VALUES.each do |key, allowed|
        value = answers[key]
        raise InvalidConfiguration, "#{key}が未回答です" if value.nil?
        if key == "profile_features"
          valid = value.is_a?(Array) && value.uniq == value && (value - allowed).empty?
          raise InvalidConfiguration, "#{key}の値が不正です: #{value.inspect}" unless valid
        else
          raise InvalidConfiguration, "#{key}の値が不正です: #{value}" unless allowed.include?(value)
        end
      end
      raise InvalidConfiguration, "PWA無効時にWeb Pushは使用できません" if self["pwa"] == "skip" && self["web_push"] == "use"

      self
    end

    private

    def normalize!
      if @values["pwa"] == "skip"
        @values["web_push"] = "skip"
        @reasons["web_push"] = "PWAを使用しないため"
      end

      return unless @values["mail"] == "auto"

      @values["mail"] = @values["account_authentication"] == "devise" ? "use" : "skip"
      @reasons["mail"] = "認証方式が#{@values['account_authentication']}のため"
    end
  end
end

# frozen_string_literal: true

module RapidRailsTemplate
  class Questionnaire
    Question = Data.define(:id, :prompt, :choices, :default, :condition, :multiple)

    QUESTIONS = [
      Question.new(:pwa, "PWAを使用しますか？", %w[use skip], "skip", nil, false),
      Question.new(:web_push, "PWAでWeb Pushを使用しますか？", %w[use skip], "skip", ->(a) { a["pwa"] == "use" }, false),
      Question.new(:active_job, "ジョブ管理を使用しますか？", %w[solid_queue skip], "skip", nil, false),
      Question.new(:solid_cache, "Solid Cacheを使用しますか？", %w[use skip], "use", nil, false),
      Question.new(:account_authentication, "アカウント管理方法を選択してください。", %w[devise wallet_siwe], "devise", nil, false),
      Question.new(:profile_features, "プロフィール機能を選択してください。", Configuration::PROFILE_FEATURES, Configuration::PROFILE_FEATURES, nil, true),
      Question.new(:api, "API機能を有効にしますか？", %w[enable disable], "enable", nil, false),
      Question.new(:action_cable, "Action Cableを使用しますか？", %w[solid_cable skip], "skip", nil, false),
      Question.new(:mail, "メール機能を使用しますか？", %w[auto use skip], "auto", nil, false),
      Question.new(:action_text, "Action Textを使用しますか？", %w[use skip], "use", nil, false),
      Question.new(:deployment, "デプロイ方法を選択してください。", %w[dokploy none], "dokploy", nil, false)
    ].freeze

    def initialize(prompt:, output: $stdout)
      @prompt = prompt
      @output = output
      @asked_question_ids = []
    end

    def ask_all(initial_answers = {})
      answers = initial_answers.transform_keys(&:to_s).dup

      QUESTIONS.each do |question|
        next if answers.key?(question.id.to_s)
        next unless question.condition.nil? || question.condition.call(answers)

        @asked_question_ids << question.id.to_s
        answers[question.id.to_s] = ask(question)
      end

      answers
    end

    def asked_any?
      !@asked_question_ids.empty?
    end

    def confirm?(summary)
      @output.puts summary
      with_prompt_error do
        @prompt.confirm(
          "この内容で実行しますか？",
          default: false,
          affirmative: "実行",
          negative: "中止"
        )
      end
    end

    private

    def ask(question)
      options = { header: question.prompt, selected: Array(question.default) }
      options[:no_limit] = true if question.multiple
      answer = with_prompt_error do
        @prompt.choose(question.choices, **options)
      end
      raise PromptError, "選択がキャンセルされました: #{question.prompt}" if answer.nil?

      if question.multiple
        valid = answer.is_a?(Array) && answer.uniq == answer && (answer - question.choices).empty?
        raise PromptError, "選択UIが不正な値を返しました: #{answer.inspect}" unless valid

        return question.choices.select { |choice| answer.include?(choice) }
      end

      raise PromptError, "選択UIが不正な値を返しました: #{answer}" unless question.choices.include?(answer)

      answer
    end

    def with_prompt_error
      yield
    rescue StandardError => e
      raise unless gum_error?(e)

      raise PromptError, "Gumの実行に失敗しました: #{e.message}"
    end

    def gum_error?(error)
      @prompt.respond_to?(:const_defined?) && @prompt.const_defined?(:Error) && error.is_a?(@prompt.const_get(:Error))
    end
  end
end

