module RapidRailsTemplate
  class ExecutionPlan
    attr_reader :configuration, :generator_options, :gems, :steps, :artifacts, :processes

    def self.build(configuration)
      new(configuration)
    end

    def initialize(configuration)
      @configuration = configuration
      @generator_options = GeneratorOptions.build(configuration)
      @gems = build_gems.freeze
      @steps = build_steps.freeze
      @artifacts = build_artifacts.freeze
      @processes = build_processes.freeze
      freeze
    end

    def to_h
      {
        "configuration" => configuration.to_h,
        "generator_options" => generator_options,
        "gems" => gems,
        "steps" => steps,
        "artifacts" => artifacts,
        "processes" => processes
      }
    end

    def summary
      lines = ["\n実行計画", "========", "実効値:"]
      configuration.values.each { |key, value| lines << "  #{key}: #{value}" }
      configuration.reasons.each { |key, reason| lines << "    (#{key}: #{reason})" }
      lines << "rails new options: #{generator_options.join(' ')}"
      lines << "Gem: #{gems.join(', ')}"
      lines << "Steps: #{steps.join(' -> ')}"
      lines << "生成物: #{artifacts.empty? ? '(なし)' : artifacts.join(', ')}"
      lines << "Production processes: #{processes.empty? ? '(未設定)' : processes.join(', ')}"
      lines.join("\n")
    end

    private

    def build_gems
      result = %w[pagy active_link_to action_policy sentry-ruby sentry-rails capybara capybara-playwright-driver factory_bot factory_bot_rails ruby-lsp ruby-lsp-rails rubocop-rails rubocop-thread_safety momocop prism]
      result << "devise" if configuration["account_authentication"] == "devise"
      result << "siwe-rb" if configuration["account_authentication"] == "wallet_siwe"
      result << "web-push" if configuration["web_push"] == "use"
      result << "solid_queue" if configuration["active_job"] == "solid_queue"
      result << "solid_cache" if configuration["solid_cache"] == "use"
      result << "solid_cable" if configuration["action_cable"] == "solid_cable"
      result << "foreman" if configuration["deployment"] == "dokploy"
      result
    end

    def build_steps
      result = %w[declare_gems install_daisyui configure_rubocop configure_test_stack configure_application_gems]
      result << (configuration["account_authentication"] == "devise" ? "install_devise" : "install_wallet_siwe")
      result << "install_active_storage" if configuration["profile_features"].include?("avatar")
      result << "configure_profile" if configuration["profile_features"].any?
      result << "configure_api" if configuration["api"] == "enable"
      result << "configure_default_views"
      result << "configure_web_push" if configuration["web_push"] == "use"
      result << "install_solid_queue" if configuration["active_job"] == "solid_queue"
      result << "install_solid_cache" if configuration["solid_cache"] == "use"
      result << "install_solid_cable" if configuration["action_cable"] == "solid_cable"
      result << "configure_dokploy" if configuration["deployment"] == "dokploy"
      result << "prepare_database"
      result << "verify"
      result
    end

    def build_artifacts
      result = %w[
        package.json
        package-lock.json
        app/assets/tailwind/application.css
        app/controllers/home_controller.rb
        app/controllers/accounts_controller.rb
        app/views/layouts/application.html.erb
        app/views/layouts/authentication.html.erb
        app/views/layouts/account.html.erb
        app/views/shared/_header.html.erb
        app/views/shared/_flash.html.erb
        app/views/shared/_footer.html.erb
        app/views/home/index.html.erb
        app/views/accounts/show.html.erb
        test/integration/default_pages_test.rb
      ]
      if configuration["api"] == "enable"
        result.concat(%w[
          app/models/api_credential.rb
          app/controllers/api/api_controller.rb
          app/controllers/api/api_credentials_controller.rb
          app/controllers/api_credentials_controller.rb
          app/javascript/controllers/clipboard_controller.js
          app/views/api_credentials/index.html.erb
          app/views/api_credentials/show.html.erb
          app/views/api_credentials/new.html.erb
          app/views/api_credentials/edit.html.erb
          app/views/api_credentials/_form.html.erb
          test/models/api_credential_test.rb
          test/controllers/api/api_credentials_controller_test.rb
          test/controllers/api_credentials_controller_test.rb
        ])
      end
      if configuration["profile_features"].any?
        result.concat(%w[
          app/models/profile.rb
          app/controllers/profiles_controller.rb
          app/views/profiles/show.html.erb
          app/views/profiles/edit.html.erb
          app/views/profiles/_form.html.erb
          config/locales/ja.yml
          test/models/profile_test.rb
        ])
      end
      if configuration["account_authentication"] == "devise"
        result.concat(%w[
          app/views/devise/sessions/new.html.erb
          app/views/devise/registrations/new.html.erb
          app/views/devise/registrations/edit.html.erb
          app/views/devise/passwords/new.html.erb
          app/views/devise/passwords/edit.html.erb
        ])
      else
        result << "app/views/sessions/new.html.erb"
        result << "app/javascript/controllers/siwe_sign_in_controller.js"
        result << "app/views/accounts/edit.html.erb"
        result << "config/locales/ja.yml"
      end
      result.concat(%w[Dockerfile.prod .dockerignore bin/docker-entrypoint Procfile.prod litestream.yml]) if configuration["deployment"] == "dokploy"
      result << "mise.local.toml" if configuration["web_push"] == "use"
      result.uniq
    end

    def build_processes
      return [] unless configuration["deployment"] == "dokploy"

      result = ["web"]
      result << "worker" if configuration["active_job"] == "solid_queue"
      result
    end
  end
end

# frozen_string_literal: true

require "json"
require "open3"
require "rbconfig"
require "tempfile"

module RapidRailsTemplate
  class Runner
    def initialize(app_path:, plan:, template_payload:, output: $stdout, error: $stderr, process_runner: Open3)
      @app_path = app_path
      @plan = plan
      @template_payload = template_payload
      @output = output
      @error = error
      @process_runner = process_runner
    end

    def run
      template_file = secure_tempfile(["rapid-rails-template", ".rb"], template_payload)
      config_file = secure_tempfile(["rapid-rails-configuration", ".json"], JSON.generate(plan.to_h))
      command = rails_command(template_file.path)
      environment = { "RAPID_RAILS_TEMPLATE_CONFIG" => config_file.path }
      status = stream_process(environment, command)
      status.exitstatus || 1
    ensure
      template_file&.close!
      config_file&.close!
    end

    private

    attr_reader :app_path, :plan, :template_payload, :output, :error, :process_runner

    def secure_tempfile(basename, content)
      file = Tempfile.new(basename)
      file.chmod(0o600)
      file.binmode
      file.write(content)
      file.flush
      file
    end

    def rails_command(template_path)
      rails = Gem.bin_path("railties", "rails", ">= 8.1", "< 8.2")
      [RbConfig.ruby, rails, "new", app_path, *plan.generator_options, "--template", template_path]
    end

    def stream_process(environment, command)
      process_runner.popen3(environment, *command) do |stdin, stdout, stderr, wait_thread|
        stdin.close
        readers = [Thread.new { IO.copy_stream(stdout, output) }, Thread.new { IO.copy_stream(stderr, error) }]
        readers.each(&:join)
        wait_thread.value
      end
    rescue SystemCallError => e
      raise Error, "rails newを起動できません: #{e.message}"
    end
  end
end


require "base64"
module RapidRailsTemplate
  APPLICATION_TEMPLATE = Base64.strict_decode64("").freeze
end

# frozen_string_literal: true

module RapidRailsTemplate
  class Entrypoint
    CLI_OPTIONS = Configuration::VALID_VALUES.to_h do |id, allowed|
      ["--#{id.tr('_', '-')}", [id, allowed]]
    end.freeze

    def self.run(argv, output: $stdout, error: $stderr, runner_class: Runner, prompt: nil)
      argument_answers, app_path = parse_arguments(argv)

      Environment.validate!
      questionnaire = Questionnaire.new(prompt: prompt || Environment.gum, output:)
      configuration = Configuration.build(questionnaire.ask_all(argument_answers))
      plan = ExecutionPlan.build(configuration)
      if questionnaire.asked_any?
        return 0 unless questionnaire.confirm?(plan.summary)
      else
        output.puts plan.summary
      end

      runner_class.new(app_path:, plan:, template_payload: APPLICATION_TEMPLATE, output:, error:).run
    rescue Error => e
      error.puts "エラー: #{e.message}"
      1
    end

    def self.parse_arguments(argv)
      answers = {}
      paths = []

      argv.each do |argument|
        unless argument.start_with?("--")
          paths << argument
          next
        end

        option, value = argument.split("=", 2)
        definition = CLI_OPTIONS[option]
        raise Error, "不明なオプションです: #{option}\n#{usage}" if definition.nil?
        id, allowed = definition
        raise Error, "#{option}が複数回指定されています" if answers.key?(id)

        answers[id] = parse_option_value(option, id, allowed, value)
      end

      raise Error, usage unless paths.length == 1

      [answers, paths.fetch(0)]
    end

    def self.usage
      options = CLI_OPTIONS.map do |option, (_, allowed)|
        separator = option == "--profile-features" ? "," : "|"
        "  #{option}=#{allowed.join(separator)}"
      end
      (["使用方法: ruby bootstrap.rb [OPTIONS] APP_PATH", "オプション:"] + options).join("\n")
    end

    def self.parse_option_value(option, id, allowed, value)
      raise Error, "#{option}には値が必要です\n#{usage}" if value.nil?

      unless id == "profile_features"
        raise Error, "#{option}には値が必要です\n#{usage}" if value.empty?
        raise Error, "#{option}の値が不正です: #{value}（#{allowed.join('/')}から選択してください）" unless allowed.include?(value)

        return value
      end

      features = value.split(",", -1)
      features = [] if value.empty?
      valid = features.uniq == features && features.none?(&:empty?) && (features - allowed).empty?
      unless valid
        raise Error, "#{option}の値が不正です: #{value}（#{allowed.join(',')}をカンマ区切りで指定してください）"
      end

      allowed.select { |feature| features.include?(feature) }
    end

    private_class_method :parse_arguments, :parse_option_value, :usage
  end
end

exit RapidRailsTemplate::Entrypoint.run(ARGV) if $PROGRAM_NAME == __FILE__
